  for (const patch of [{ radiusMm: 14 }, { radiusMm: 41 }, { rodLengthMm: 74 }, { rodLengthMm: 181 }, { radiusMm: 40, rodLengthMm: 119 }, { rpm: 31 }, { rpm: -31 }, { rpm: NaN }, { radiusMm: Infinity }]) {
