test('the six-axis length Jacobian stays nonsingular and equal actuator rates produce pure heave', () => {
  const legs = fixtureLegs(buildStewartPlatformDemo());
  const radius = STEWART_DEFAULTS.platformAnchorRadiusMm;
  for (let step = 0; step <= 24; step++) {
    const time = step / 4;
    const reference = stewartHeaveReference(time);
    const jacobian = legs.map((leg) => {
      const delta = sub(add(leg.deckLocal, reference.platformPositionMm), leg.base);
      const axis = scale(delta, 1 / norm(delta));
      return [...axis, ...scale(cross(leg.deckLocal, axis), 1 / radius)];
    });
    const { solution, minimumPivot } = solve(jacobian, Array(6).fill(2));
    assert(minimumPivot > 0.25, `poorly conditioned pivot ${minimumPivot}`);
    near([solution[0], solution[1], ...solution.slice(3)], [0, 0, 0, 0, 0], 1e-9);
    const legLength = norm(sub(add(legs[0].deckLocal, reference.platformPositionMm), legs[0].base));
    const vertical = reference.platformPositionMm[2] - legs[0].base[2];
    assert.ok(Math.abs(solution[2] - 2 * legLength / vertical) < 1e-10);
    for (const leg of legs) {
      const initial = norm(sub(leg.deck, leg.base));
      const current = norm(sub(add(leg.deckLocal, reference.platformPositionMm), leg.base));
      assert.ok(Math.abs(current - initial - 2 * time) < 1e-10);
    }
  }
  assert.ok(Math.abs(stewartHeaveReference(6).platformPositionMm[2] - 172.83662094518425) < 1e-10);
});

test('sampled lift retains rod overlap, radial bore clearance and conservative separation between legs', () => {
  const p = STEWART_DEFAULTS;
  const legs = fixtureLegs(buildStewartPlatformDemo());
  assert.equal(p.boreRadiusMm - p.rodRadiusMm, 0.5);
  for (let step = 0; step <= 60; step++) {
    const reference = stewartHeaveReference(step / 10);
    assert(reference.remainingRodInsertionMm >= 20 - 1e-9);
    assert(reference.extensionMm <= p.maximumStrokeMm);
    const segments = legs.map((leg) => [leg.base, add(leg.deckLocal, reference.platformPositionMm)]);
    for (let a = 0; a < segments.length; a++) for (let b = a + 1; b < segments.length; b++) {
      const distance = segmentDistance(...segments[a], ...segments[b]);
      // Radius9 capsules enclose sleeve, collar, shaft and end balls.
      assert(distance > 2 * p.collarRadiusMm, `actuator capsules overlap: legs ${a + 1},${b + 1}, d=${distance}`);
    }
    for (const [base, deck] of segments) {
      const axis = scale(sub(deck, base), 1 / norm(sub(deck, base)));
      const horizontal = Math.hypot(axis[0], axis[1]);
      const sphereNeck = Math.sqrt(p.ballRadiusMm ** 2 - p.rodRadiusMm ** 2);
      assert(sphereNeck * axis[2] - p.rodRadiusMm * horizontal > 0, 'neck should clear the adjacent plate face');
      assert(10 * axis[2] - p.barrelRadiusMm * horizontal > 0, 'barrel must start above the base plate');
      assert(p.bearingSeatRadiusMm > p.ballRadiusMm, 'the spherical ends must fit their plate clearance bores');
    }
  }
});

test('the builder rejects an unsafe programme or insufficient rod overlap', () => {
  assert.throws(() => buildStewartPlatformDemo({ durationMs: 11000 }), /exceeds the designed stroke/);
  assert.throws(() => buildStewartPlatformDemo({ initialRodInsertionMm: 25 }), /At least 10 mm/);
});

test('saved six-axis command survives demo parsing and invalid commands fail closed', () => {
  const document = fixture();
  document.state.simulation.stewartMotion = { kind: 'six-axis', target: { translationMm: [4, -3, 4], rotationDeg: [1.5, -1, 2] }, moveDurationMs: 4000, settleDurationMs: 2000 };
  assert.deepEqual(parseDemoDocument(document).state.simulation.stewartMotion, document.state.simulation.stewartMotion);
  document.state.simulation.stewartMotion.target.rotationDeg[0] = 8;
  assert.throws(() => parseDemoDocument(document), /workspace/);
});

test('source guard permits labels and material changes but rejects altered solids, topology and visibility', () => {
  const reference = fixture().state.assembly;
  const renamed = structuredClone(reference);
  renamed.parts[0].name = 'My stand'; renamed.parts[0].materialId = 'brass-c36000';
  validateStewartSourceGeometry(renamed, reference);
  for (const edit of [
    a => { a.parts[1].features[0].distance = 999; },
    a => { a.parts[1].sketches[0].primitives[0].radius = 200; },
    a => { a.parts[1].transform.positionMm[0] = 1; },
    a => { a.parts[1].visible = false; },
    a => { a.mates.pop(); },
    a => { a.booleanFeatures.push({ id: 'extra' }); },
  ]) {
    const modified = structuredClone(reference); edit(modified);
    assert.throws(() => validateStewartSourceGeometry(modified, reference), /original Stewart geometry/);
  }
});

test('measurement state uses actual worker results, holds on zero step, and clears on reset or another experiment', () => {
  const measurement = { phase: 'moving', positionErrorMm: 0.013, actualTranslationMm: [1,2,3] };
  const transforms = [{partId: 'stewart-platform', positionMm: [1,2,163], rotationQuat: [0,0,0,1]}];
  publishPoseMeasurements({dtMs: 10, transforms, stewartMeasurement: measurement});
  assert.equal(usePoseMeasurements.getState().stewart, measurement);
  assert.equal(usePoseMeasurements.getState().poses, transforms);
  publishPoseMeasurements({dtMs: 0, transforms: []});
  assert.equal(usePoseMeasurements.getState().stewart, measurement);
  clearPoseMeasurements();
  assert.equal(usePoseMeasurements.getState().stewart, undefined);
  assert.deepEqual(usePoseMeasurements.getState().poses, []);
  publishPoseMeasurements({dtMs: 10, transforms, stewartMeasurement: measurement});
  publishPoseMeasurements({dtMs: 10, transforms: []});
  assert.equal(usePoseMeasurements.getState().stewart, undefined);
});

test('the entire ±5 mm / ±2° pose box is enclosed with no unresolved cells', () => {
  const report = certifyStewartWorkspace();
  assert.equal(report.certified, true);
  assert.deepEqual(report.unresolvedCells, []);
  assert.ok(report.acceptedCells > 1, 'must subdivide, not relabel corner samples as an enclosure');
  assert.ok(report.minStrokeBoundMm >= -12 && report.maxStrokeBoundMm <= 20);
  assert.ok(report.minCapsuleGapBoundMm > 8);
  assert.ok(report.minPlateNeckGapBoundMm > 1.8);
  assert.ok(report.maxRelativeBearingBoundDeg <= 8);
  assert.ok(report.maxJacobianConditionBound < 100);
  assert.ok(STEWART_DEFAULTS.initialRodInsertionMm - report.maxStrokeBoundMm > 12);
  assert.ok(STEWART_DEFAULTS.barrelLengthMm - STEWART_DEFAULTS.initialRodInsertionMm + report.minStrokeBoundMm > 16);
});

test('insufficient subdivision and an enlarged unsafe range fail explicitly', () => {
  assert.equal(certifyStewartWorkspace(WORKSPACE_LIMITS, 0).certified, false);
  assert.equal(certifyStewartWorkspace({ ...WORKSPACE_LIMITS, translationMm: 30 }, 6).certified, false);
});

test('independent Rodrigues progress matches exact quaternion axis-angle interpolation at intermediate poses', () => {
  const q = new Quaternion().setFromEuler(new Euler(...target.rotationDeg.map((v) => v * Math.PI / 180), 'XYZ'));
  for (const s of [0, 0.1, 0.3, 0.7, 1]) {
    const pose = poseAtProgress(target, s);
    // Three's convenience slerp switches to normalized lerp for small angles.
    // The controller deliberately uses exact angular progress, so compare to
    // its independent axis-angle definition, not that fast approximation.
    const theta = 2 * Math.acos(q.w);
    const axis = theta < 1e-9 ? new Vector3(0, 0, 1) : new Vector3(q.x, q.y, q.z).normalize();
    const expected = new Quaternion().setFromAxisAngle(axis, theta * s);
    for (const p of [[75, 0, 0], [0, 75, 0], [0, 0, 1], [17, -33, 41]]) {
      near(matrixPoint(pose.rotationMatrix, p), new Vector3(...p).applyQuaternion(expected).toArray());
    }
    near(pose.translationMm, target.translationMm.map((v) => v * s));
  }
});

test('all 64 extreme home-to-target paths are enclosed between progress samples', () => {
  for (let bits = 0; bits < 64; bits++) {
    const target = { translationMm: [0, 1, 2].map((i) => bits & (1 << i) ? 5 : -5), rotationDeg: [3, 4, 5].map((i) => bits & (1 << i) ? 2 : -2) };
    const report = certifyStewartMotion(target);
    assert.equal(report.certified, true, JSON.stringify({ target, failures: report.failures }));
    assert.ok(report.maxActuatorSpeedBoundMmPerSec < 8);
  }
});

test('exact target solid placements close spherical endpoints and encode independent rod extension', () => {
  const source = buildStewartPlatformDemo().state.assembly;
  const transforms = new Map(stewartPoseTransforms(target).map((tx) => [tx.partId, tx]));
  const point = (id, local) => {
    const tx = transforms.get(id);
    return matrixPoint(tx.rotationMatrix, local).map((v, i) => v + tx.positionMm[i]);
  };
  for (const mate of source.mates.filter((m) => m.type === 'spherical')) near(point(mate.partA, mate.pivotA.localPoint), point(mate.partB, mate.pivotB.localPoint));
  const result = analyseStewartPose(target);
  for (let i = 1; i <= 6; i++) {
    const tx = transforms.get(`stewart-barrel-${i}`), rod = transforms.get(`stewart-rod-${i}`);
    const displacement = rod.positionMm.map((v, j) => v - tx.positionMm[j]);
    near(displacement, result.legs[i - 1].direction.map((v) => v * result.legs[i - 1].extensionMm));
    const m = new Matrix4().set(...[0, 1, 2].flatMap((r) => [...tx.rotationMatrix.slice(r * 3, r * 3 + 3), 0]), 0, 0, 0, 1);
    assert.ok(Math.abs(m.determinant() - 1) < 1e-10);
  }
});

